<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Weddings Catering - UX Analysis</title>
    <style>
        :root {
            --primary-gold: #cfaa6d;
            --text-dark: #333;
            --text-light: #666;
            --bg-cream: #f9f9f7;
            --font-serif: 'Georgia', 'Times New Roman', serif;
            --font-sans: 'Helvetica Neue', 'Helvetica', Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-sans);
            color: var(--text-dark);
            line-height: 1.6;
            background-color: #fff;
        }

        /* Utilities */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .flex { display: flex; }
        .grid { display: grid; }
        .items-center { align-items: center; }
        .justify-center { justify-content: center; }
        .text-center { text-align: center; }
        .uppercase { text-transform: uppercase; }

        a { text-decoration: none; color: inherit; transition: opacity 0.3s; }
        a:hover { opacity: 0.7; }

        /* Header */
        header {
            position: absolute;
            top: 0;
            width: 100%;
            z-index: 10;
            padding: 15px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            color: white;
            font-size: 11px;
            letter-spacing: 1px;
            font-weight: 600;
        }

        nav ul {
            list-style: none;
            display: flex;
            gap: 25px;
        }

        /* Hero */
        .hero {
            height: 350px;
            background-image: linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url('https://images.unsplash.com/photo-1519741497674-611481863552?ixlib=rb-1.2.1&auto=format&fit=crop&w=1950&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            justify-content: center;
            align-items: center;
            color: white;
        }

        .hero h1 {
            font-size: 64px;
            font-weight: 800;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        /* Intro Section */
        .intro-section {
            padding: 60px 0;
            background-color: #fff;
        }

        .intro-grid {
            display: grid;
            grid-template-columns: 35% 65%;
            gap: 50px;
            align-items: start;
        }

        .intro-img {
            width: 100%;
            height: 450px;
            object-fit: cover;
            box-shadow: 0 10px 30px rgba(0,0,0,0.1);
        }

        .intro-content h2 {
            font-family: var(--font-serif);
            font-style: italic;
            color: var(--primary-gold);
            font-size: 28px;
            margin-bottom: 5px;
            font-weight: normal;
        }

        .intro-content h3 {
            font-size: 24px;
            text-transform: uppercase;
            margin-bottom: 20px;
            letter-spacing: 1px;
        }

        .intro-text {
            font-size: 13px;
            color: var(--text-light);
            margin-bottom: 20px;
            max-width: 90%;
        }

        .form-container {
            background-color: #fcfcfc;
            padding: 20px;
            border: 1px solid #eee;
            margin-top: 20px;
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 15px;
            margin-bottom: 15px;
        }

        input, select, textarea {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            background: #fff;
            font-family: inherit;
            font-size: 13px;
            outline: none;
        }

        textarea { resize: vertical; min-height: 80px; grid-column: span 2; }

        .btn-submit {
            background-color: var(--primary-gold);
            color: white;
            border: none;
            padding: 12px 30px;
            cursor: pointer;
            font-weight: bold;
            text-transform: uppercase;
            font-size: 12px;
            letter-spacing: 1px;
            float: right;
        }

        /* Packages Section */
        .packages-section {
            padding: 60px 0;
            background-color: var(--bg-cream);
            text-align: center;
        }

        .section-title-sub {
            font-family: var(--font-serif);
            font-style: italic;
            color: var(--primary-gold);
            font-size: 22px;
            margin-bottom: 5px;
        }

        .section-title-main {
            font-size: 32px;
            text-transform: uppercase;
            margin-bottom: 10px;
            letter-spacing: 1px;
        }

        .divider {
            width: 40px;
            height: 2px;
            background-color: var(--primary-gold);
            margin: 0 auto 30px auto;
        }

        .includes-text {
            max-width: 600px;
            margin: 0 auto 40px auto;
            font-size: 14px;
            color: var(--text-dark);
            line-height: 1.8;
        }

        .style-header {
            background-color: #111;
            color: white;
            padding: 15px;
            text-transform: uppercase;
            font-weight: bold;
            letter-spacing: 1px;
            font-size: 14px;
            margin-bottom: 0;
        }

        .styles-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            background: white;
            text-align: center;
        }

        .style-card {
            padding: 40px 20px;
            border-right: 1px solid #eee;
        }
        .style-card:last-child { border-right: none; }

        .style-card h4 {
            font-size: 16px;
            text-transform: uppercase;
            margin-bottom: 10px;
        }

        .price {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 20px;
            display: block;
        }

        .style-desc {
            font-size: 11px;
            color: var(--text-light);
            line-height: 1.6;
            max-width: 250px;
            margin: 0 auto;
        }

        /* Menu Detail Section */
        .menu-detail-section {
            padding: 60px 0;
            background-color: #fff;
        }

        .detail-header {
            text-align: center;
            margin-bottom: 50px;
        }
        .detail-header h2 {
            font-size: 24px;
            text-transform: uppercase;
            font-weight: 700;
        }

        .menu-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 40px;
            font-size: 12px;
            color: #555;
        }

        .menu-col h4 {
            font-size: 11px;
            text-transform: uppercase;
            color: #000;
            margin-bottom: 15px;
            font-weight: 700;
        }

        .menu-list li {
            list-style: none;
            margin-bottom: 8px;
            line-height: 1.4;
        }

        /* Footer */
        footer {
            background-color: #1a2332;
            color: #889bb0;
            padding: 60px 0 30px 0;
            font-size: 12px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 30px;
            margin-bottom: 40px;
        }

        .footer-col h5 {
            color: white;
            text-transform: uppercase;
            margin-bottom: 20px;
            font-size: 13px;
            font-weight: 700;
        }

        .footer-col ul { list-style: none; }
        .footer-col li { margin-bottom: 8px; }
        .footer-col a:hover { color: var(--primary-gold); }

        .copyright {
            text-align: center;
            border-top: 1px solid rgba(255,255,255,0.05);
            padding-top: 20px;
            font-size: 11px;
        }

        /* Responsive */
        @media (max-width: 900px) {
            .intro-grid { grid-template-columns: 1fr; }
            .intro-img { height: 300px; order: -1; }
            .styles-grid { grid-template-columns: 1fr; }
            .style-card { border-right: none; border-bottom: 1px solid #eee; }
            .menu-grid { grid-template-columns: 1fr; }
            header { display: none; } /* Simplified for mobile view */
            .footer-grid { grid-template-columns: 1fr 1fr; }
        }
    </style>
</head>
